export class EntropySelfConsistency {
  calculateEntropy(probabilities) {
    return -probabilities.reduce((sum, p) => sum + p * Math.log2(p), 0);
  }

  evaluateChains(chains) {
    return chains.map(chain => {
      const probabilities = chain.map(step => step.probability);
      const entropy = this.calculateEntropy(probabilities);
      return { chain, entropy };
    });
  }
}